from copy import deepcopy
from datetime import datetime
import sqlite3
import unittest

import categories
import config
import database
import training_catalogue


NOW = datetime(2026, 11, 15, 12)
PROOF_URL = (config.UNISPORT_SCHEDULE_API_URL
             + '?startDateMin=2026-11-16&startDateMax=2026-11-22'
             + '&showBookingsFull=true&showCourses=true')


class TrainingCatalogueTests(unittest.TestCase):
    """Build disposable runtime catalogues from synthetic private fixtures only."""

    def setUp(self):
        """Create sparse-ID source data with deliberate private fields and a fresh target."""
        self.source = database.get_connection(':memory:')
        self.target = database.get_connection(':memory:')
        self.addCleanup(self.source.close)
        self.addCleanup(self.target.close)
        database.init_db(self.source)
        database.init_db(self.target)
        taxonomy = categories.load_taxonomy()
        categories.seed_categories(self.source, taxonomy)
        categories.seed_categories(self.target, taxonomy)
        bundle = self.source.execute('SELECT id FROM bundles WHERE key=?',
                                     ('sports_racket',)).fetchone()['id']
        with self.source:
            self.source.execute('''INSERT INTO training_imports
                (id,file_name,source_fingerprint,imported_at) VALUES (?,?,?,?)''',
                (8, 'PRIVATE_ARCHIVE.csv', 'private-source-hash', '2026-11-15 09:00:00'))
            self.source.execute('''INSERT INTO training_history
                (id,import_id,source_row,sport,variant,weekday_text,start_time,date_original,
                 training_date,participants_signed_up,participants_teacher,max_participants)
                VALUES (1,8,2,'PRIVATE_SPORT','PRIVATE_PERSON_NOTE','Montag','07:00',
                        'Montag, 2. November 2026','2026-11-02',17,21,9999)''')
            for series_id, external_id in ((17, 'history-pattern:1'), (19, 'history-pattern:2')):
                self.source.execute('''INSERT INTO series
                    (id,source,external_id,title,description,organizer,bundle_id,sport,level,
                     location,location_type,source_url,registration_url,price_rappen,
                     members_only,is_recurring)
                    VALUES (?,'unisport',?,'PRIVATE_COURSE_TITLE','PRIVATE_PERSON_NOTE',
                            'PRIVATE_ORGANIZER',?,'PRIVATE_SPORT','PRIVATE_LEVEL',
                            'PRIVATE_VENUE','st_gallen','https://private.invalid/source',
                            'https://private.invalid/register',999900,1,1)''',
                    (series_id, external_id, bundle))
            self.source.execute('''INSERT INTO events
                (id,series_id,start_time,end_time,end_is_estimated,status)
                VALUES (42,17,'2026-11-16 07:00:00','2026-11-16 08:00:00',0,'unknown'),
                       (44,19,'2026-11-17 18:00:00','2026-11-17 19:30:00',1,'unknown')''')
            self.source.execute('''INSERT INTO event_provenance
                (event_id,kind,forecast_anchor_date,evidence_weeks,created_at,
                 verification_url,verified_at)
                VALUES (42,'website','2026-11-06',3,'2026-11-15 09:00:00',?,
                        '2026-11-15 10:00:00'),
                       (44,'projected','2026-11-06',4,'2026-11-15 09:00:00',NULL,NULL)''',
                (PROOF_URL,))
        database.create_user(self.source, 'Private Person', now=NOW)
        self.approvals = [{'external_id': 'history-pattern:1', 'product_id': 66,
                           'public_title': 'Tennis - Level 1',
                           'appointment_description': 'Public short session'}]

    def build(self, approvals=None):
        """Call the public builder with explicit disposable source and target connections."""
        return training_catalogue.build_training_catalogue(
            self.source, self.target, self.approvals if approvals is None else approvals)

    def state(self, connection):
        """Capture data through fixed SQL statements rather than interpolated table names."""
        queries = ['SELECT * FROM series ORDER BY id', 'SELECT * FROM events ORDER BY id',
                   'SELECT * FROM event_provenance ORDER BY event_id',
                   'SELECT * FROM training_imports ORDER BY id',
                   'SELECT * FROM training_history ORDER BY id',
                   'SELECT * FROM users ORDER BY id', 'SELECT * FROM app_settings ORDER BY key']
        # Course: L04 – a list of independent SQL snapshots makes retained values comparable.
        return [[tuple(row) for row in connection.execute(query).fetchall()]
                for query in queries]

    def test_public_whitelist_and_unapproved_mask_preserve_identity(self):
        """Copy reviewed labels and dates while masking every unapproved private course field."""
        report = self.build()
        self.assertEqual((report['n_series'], report['n_events']), (2, 2))
        self.assertEqual((report['n_created'], report['n_existing']), (2, 0))
        self.assertEqual(report['n_masked_series'], 1)
        public = self.target.execute('SELECT * FROM series WHERE id=?', (17,)).fetchone()
        self.assertEqual(public['external_id'], 'history-pattern:1')
        self.assertEqual(public['title'], 'Tennis - Level 1 · Public short session')
        self.assertEqual(public['sport'], 'Tennis - Level 1')
        self.assertEqual(public['level'], '')
        self.assertEqual(public['description'], config.TRAINING_CATALOGUE_DESCRIPTION)
        self.assertEqual(public['organizer'], 'Unisport HSG')
        self.assertEqual(public['source_url'], config.UNISPORT_PUBLIC_SCHEDULE_URL)
        self.assertEqual((public['location'], public['location_type']), ('', 'tba'))
        self.assertEqual(public['registration_url'], '')
        self.assertIsNone(public['price_rappen'])
        self.assertEqual((public['members_only'], public['is_placeholder']), (0, 0))
        masked = self.target.execute('SELECT * FROM series WHERE id=?', (19,)).fetchone()
        self.assertEqual(masked['title'], config.UNREVIEWED_ACTIVITY_TITLE)
        self.assertEqual((masked['sport'], masked['level']), ('', ''))
        self.assertEqual([tuple(row) for row in self.target.execute(
            'SELECT id,series_id,status FROM events ORDER BY id')],
            [(42, 17, 'unknown'), (44, 19, 'unknown')])
        self.assertEqual(database.get_setting(self.target, 'catalogue_mode'),
                         config.REVIEWED_CATALOGUE_MODE)
        self.assertEqual(database.get_setting(self.target, 'catalogue_id'), report['catalogue_id'])
        self.assertEqual(database.get_setting(self.target, 'setup_done'), '1')

    def test_archive_users_and_private_values_never_enter_runtime(self):
        """Retain the complete source and create no copies of archive rows or private users."""
        original = self.state(self.source)
        self.build()
        self.assertEqual(self.state(self.source), original)
        for query in ('SELECT COUNT(*) FROM training_history',
                      'SELECT COUNT(*) FROM training_imports',
                      'SELECT COUNT(*) FROM users', 'SELECT COUNT(*) FROM interactions'):
            self.assertEqual(self.target.execute(query).fetchone()[0], 0)
        exported = '\n'.join(self.target.iterdump())
        for private in ('PRIVATE_', 'private.invalid', 'Private Person', 'private-source-hash'):
            self.assertNotIn(private, exported)

    def test_provenance_dates_and_estimates_are_retained_exactly(self):
        """Keep publication proof separate from projected dates and unknown availability."""
        self.build()
        for query in ('SELECT * FROM events ORDER BY id',
                      'SELECT * FROM event_provenance ORDER BY event_id'):
            self.assertEqual([tuple(row) for row in self.target.execute(query)],
                             [tuple(row) for row in self.source.execute(query)])
        bundle = self.target.execute('''SELECT b.key FROM series s
            JOIN bundles b ON b.id=s.bundle_id WHERE s.id=?''', (17,)).fetchone()[0]
        self.assertEqual(bundle, 'sports_racket')
        self.assertEqual(self.target.execute('PRAGMA integrity_check').fetchone()[0], 'ok')
        self.assertEqual(self.target.execute('PRAGMA foreign_key_check').fetchall(), [])

    def test_repeat_preserves_profile_manual_edits_and_catalogue_id(self):
        """An identical source is a no-op even after local profile and planning edits."""
        first = self.build()
        user_id = database.create_user(self.target, 'Alex', now=NOW)
        with self.target:
            self.target.execute('UPDATE series SET title=? WHERE id=?', ('Curated title', 17))
            self.target.execute('UPDATE events SET end_time=? WHERE id=?',
                                ('2026-11-17 20:00:00', 44))
        before = self.state(self.target)
        second = self.build()
        self.assertEqual((second['n_created'], second['n_existing']), (0, 2))
        self.assertEqual(second['catalogue_id'], first['catalogue_id'])
        self.assertEqual(self.state(self.target), before)
        self.assertEqual(database.get_user_profile(self.target, user_id).display_name, 'Alex')

    def test_source_revision_rejects_existing_catalogue_without_replacing_data(self):
        """A changed source payload needs a fresh review rather than silently replacing IDs."""
        self.build()
        before = self.state(self.target)
        with self.source:
            self.source.execute('UPDATE events SET end_time=? WHERE id=?',
                                ('2026-11-16 08:15:00', 42))
        with self.assertRaises(ValueError):
            self.build()
        self.assertEqual(self.state(self.target), before)

    def test_approval_revision_rejects_existing_catalogue(self):
        """Changed public labels also require a deliberate fresh catalogue preparation."""
        self.build()
        before = self.state(self.target)
        changed = deepcopy(self.approvals)
        changed[0]['public_title'] = 'Different reviewed activity'
        with self.assertRaises(ValueError):
            self.build(changed)
        self.assertEqual(self.state(self.target), before)

    def test_nonempty_unrelated_target_is_not_overwritten(self):
        """A target with an existing local profile cannot be repurposed as a fresh catalogue."""
        database.create_user(self.target, 'Existing User', now=NOW)
        before = self.state(self.target)
        with self.assertRaises(ValueError):
            self.build()
        self.assertEqual(self.state(self.target), before)

    def test_private_archive_target_is_rejected(self):
        """Never convert or clear the source archive in place."""
        before = self.state(self.source)
        with self.assertRaises(ValueError):
            training_catalogue.build_training_catalogue(
                self.source, self.source, self.approvals)
        self.assertEqual(self.state(self.source), before)

    def test_website_requires_reviewed_course_approval(self):
        """Publication metadata alone cannot authorize exporting the raw private course title."""
        with self.assertRaises(ValueError):
            self.build([])
        self.assertEqual(self.target.execute('SELECT COUNT(*) FROM events').fetchone()[0], 0)

    def test_unverified_availability_and_missing_provenance_are_rejected(self):
        """New source states need review and cannot silently enter the checked runtime data."""
        with self.source:
            self.source.execute('UPDATE events SET status=? WHERE id=?', ('open', 42))
        with self.assertRaises(ValueError):
            self.build()
        with self.source:
            self.source.execute('UPDATE events SET status=? WHERE id=?', ('unknown', 42))
            self.source.execute('DELETE FROM event_provenance WHERE event_id=?', (44,))
        with self.assertRaises(ValueError):
            self.build()
        self.assertEqual(self.target.execute('SELECT COUNT(*) FROM events').fetchone()[0], 0)

    def test_invalid_or_duplicate_approvals_write_nothing(self):
        """Reject contradictory or incomplete approval data before creating active rows."""
        malformed = deepcopy(self.approvals)
        malformed[0]['public_title'] = ''
        duplicate = self.approvals + deepcopy(self.approvals)
        for approvals in (malformed, duplicate):
            with self.subTest(approvals=approvals):
                with self.assertRaises(ValueError):
                    self.build(approvals)
                count = self.target.execute('SELECT COUNT(*) FROM series').fetchone()[0]
                self.assertEqual(count, 0)

    def test_pending_caller_transactions_are_not_committed(self):
        """Reject a caller-owned transaction rather than absorbing or committing its writes."""
        self.target.execute('INSERT INTO app_settings (key,value) VALUES (?,?)',
                            ('pending', 'caller'))
        self.assertTrue(self.target.in_transaction)
        with self.assertRaises(ValueError):
            self.build()
        self.assertTrue(self.target.in_transaction)
        self.target.rollback()
        self.assertEqual(self.target.execute('SELECT COUNT(*) FROM events').fetchone()[0], 0)

    def test_forced_write_failure_rolls_back_all_activity_rows(self):
        """A later event failure cannot leave an incomplete catalogue or active mode marker."""
        self.target.execute('''CREATE TRIGGER reject_second_catalogue_event
            BEFORE INSERT ON events WHEN NEW.id=44
            BEGIN SELECT RAISE(ABORT,'forced catalogue failure'); END''')
        self.target.commit()
        with self.assertRaises(sqlite3.Error):
            self.build()
        for query in ('SELECT COUNT(*) FROM series', 'SELECT COUNT(*) FROM events',
                      'SELECT COUNT(*) FROM event_provenance'):
            self.assertEqual(self.target.execute(query).fetchone()[0], 0)
        self.assertIsNone(database.get_setting(self.target, 'catalogue_id'))
        self.assertIsNone(database.get_setting(self.target, 'catalogue_mode'))
        self.assertFalse(self.target.in_transaction)
